import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import Layout from '../../components/Layout';
import StatusBadge from '../../components/StatusBadge';
import API from '../../api/axios';

// Downloads a file via axios (sends JWT token), triggers browser save dialog
const downloadFile = async (url, filename) => {
  try {
    const response = await API.get(url, { responseType: 'blob' });
    const blob = new Blob([response.data]);
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(link.href);
  } catch (err) {
    toast.error('Download failed. Please try again.');
  }
};

export default function CustomerOrderDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);
  const [accepting, setAccepting] = useState(false);
  const [editNote, setEditNote] = useState('');
  const [requesting, setRequesting] = useState(false);
  const [showEditForm, setShowEditForm] = useState(false);

  const fetchOrder = () => {
    API.get(`/customer/orders/${id}`)
      .then(({ data }) => setOrder(data.order))
      .catch(() => navigate('/customer/orders'))
      .finally(() => setLoading(false));
  };

  useEffect(() => { fetchOrder(); }, [id]); // eslint-disable-line

  const handleAccept = async () => {
    setAccepting(true);
    try {
      const { data } = await API.post(`/customer/orders/${id}/accept`);
      toast.success('Quotation accepted! Order confirmed.');
      setOrder(data.order);
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to accept');
    } finally {
      setAccepting(false);
    }
  };

  const handleRequestEdit = async (e) => {
    e.preventDefault();
    if (!editNote.trim()) { toast.error('Please describe what needs to change'); return; }
    setRequesting(true);
    try {
      const { data } = await API.post(`/customer/orders/${id}/request-edit`, { note: editNote });
      toast.success('Edit request sent to store!');
      setOrder(data.order);
      setShowEditForm(false);
      setEditNote('');
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to send request');
    } finally {
      setRequesting(false);
    }
  };

  if (loading) return <Layout title="Order Detail"><div className="spinner" /></Layout>;
  if (!order) return <Layout title="Order Detail"><div className="alert alert-error">Order not found.</div></Layout>;

  // Owner has sent a quotation if invoiceSentToCustomer or quotationSentByOwner
  const ownerSentQuotation = order.quotationSentByOwner || order.invoiceSentToCustomer;
  const canRespond = ownerSentQuotation && !order.quotationAccepted && order.status !== 'cancelled' && order.status !== 'completed';

  return (
    <Layout title={`Quotation — ${order.orderNumber}`}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1.5rem', flexWrap: 'wrap' }}>
        <button className="btn btn-ghost btn-sm" onClick={() => navigate('/customer/orders')}>← My Orders</button>
        <h1 className="page-title" style={{ margin: 0 }}>{order.orderNumber}</h1>
        <StatusBadge status={order.status} />
        {order.quotationAccepted && (
          <span className="badge badge-green">✓ Accepted</span>
        )}
        {order.editRequested && !order.quotationAccepted && (
          <span className="badge badge-yellow">✏️ Edit Requested</span>
        )}
      </div>

      {/* ── Customer Action Banner ── */}
      {canRespond && (
        <div style={{
          background: 'linear-gradient(135deg, #f0fdf4, #dcfce7)',
          border: '1.5px solid #86efac', borderRadius: '0.75rem',
          padding: '1.25rem 1.5rem', marginBottom: '1.5rem',
          display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem'
        }}>
          <div>
            <div style={{ fontWeight: 700, color: '#166534', fontSize: '0.95rem' }}>
              📋 Quotation ready — please review and respond
            </div>
            <div style={{ fontSize: '0.8rem', color: '#4ade80', marginTop: '0.2rem', color: '#16a34a' }}>
              Final Total: <strong style={{ fontSize: '1rem' }}>{order.total?.toFixed(2)}</strong>
              {order.tax > 0 && <span style={{ marginLeft: '0.75rem', color: '#6b7280' }}>incl. tax {order.tax?.toFixed(2)}</span>}
              {order.discount > 0 && <span style={{ marginLeft: '0.75rem', color: '#16a34a' }}>− discount {order.discount?.toFixed(2)}</span>}
            </div>
          </div>
          <div style={{ display: 'flex', gap: '0.75rem', flexWrap: 'wrap' }}>
            <button
              className="btn btn-success"
              onClick={handleAccept}
              disabled={accepting}
            >
              {accepting ? 'Accepting…' : '✅ Accept Quotation'}
            </button>
            <button
              className="btn btn-outline"
              style={{ color: '#d97706', borderColor: '#d97706' }}
              onClick={() => setShowEditForm(!showEditForm)}
            >
              ✏️ Request Edit
            </button>
          </div>
        </div>
      )}

      {/* Edit request form */}
      {showEditForm && (
        <form onSubmit={handleRequestEdit}>
          <div className="card" style={{ marginBottom: '1.5rem', background: '#fffbeb', border: '1.5px solid #fcd34d' }}>
            <h3 style={{ fontWeight: 700, marginBottom: '0.75rem', fontSize: '0.95rem', color: '#92400e' }}>
              ✏️ Describe what you'd like changed
            </h3>
            <div className="form-group" style={{ marginBottom: '0.75rem' }}>
              <textarea
                className="form-textarea"
                style={{ minHeight: 80 }}
                value={editNote}
                onChange={(e) => setEditNote(e.target.value)}
                placeholder="e.g. Please remove item X, apply 10% discount, change quantity of Y to 3…"
                autoFocus
              />
            </div>
            <div style={{ display: 'flex', gap: '0.75rem' }}>
              <button type="submit" className="btn btn-warning" disabled={requesting}>
                {requesting ? 'Sending…' : '📤 Send Edit Request'}
              </button>
              <button type="button" className="btn btn-ghost" onClick={() => { setShowEditForm(false); setEditNote(''); }}>
                Cancel
              </button>
            </div>
          </div>
        </form>
      )}

      {/* Edit request already sent */}
      {order.editRequested && !order.quotationAccepted && (
        <div className="alert alert-info" style={{ marginBottom: '1.5rem' }}>
          ✏️ <strong>Edit request sent to store.</strong> Waiting for owner to update the quotation.
          <div style={{ marginTop: '0.35rem', fontSize: '0.8rem' }}>
            Your note: <em>"{order.editRequestNote}"</em>
          </div>
        </div>
      )}

      {/* Accepted banner */}
      {order.quotationAccepted && (
        <div className="alert alert-success" style={{ marginBottom: '1.5rem' }}>
          ✅ <strong>You accepted this quotation.</strong> The store is processing your order.
        </div>
      )}

      <div className="grid-2" style={{ alignItems: 'start' }}>

        {/* ── Left: Quotation document ── */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
          <div className="card" style={{ padding: 0, overflow: 'hidden' }}>

            {/* Quotation header */}
            <div style={{
              background: 'linear-gradient(135deg, #1e40af, #3b82f6)',
              color: '#fff', padding: '1.25rem 1.5rem',
              display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: '0.5rem'
            }}>
              <div>
                <div style={{ fontSize: '0.75rem', opacity: 0.8, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                  {ownerSentQuotation ? 'Final Quotation' : 'Draft Quotation'}
                </div>
                <div style={{ fontSize: '1.25rem', fontWeight: 700 }}>{order.orderNumber}</div>
                <div style={{ fontSize: '0.8rem', opacity: 0.85, marginTop: '0.2rem' }}>
                  {new Date(order.createdAt).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}
                </div>
              </div>
              <div style={{ textAlign: 'right' }}>
                <div style={{ fontSize: '0.75rem', opacity: 0.8 }}>Store</div>
                <div style={{ fontWeight: 600 }}>{order.storeName}</div>
              </div>
            </div>

            {/* Customer info strip */}
            <div style={{ padding: '0.85rem 1.5rem', background: '#f8fafc', borderBottom: '1px solid #e5e7eb', display: 'flex', gap: '2rem', flexWrap: 'wrap', fontSize: '0.8rem' }}>
              <div><span style={{ color: '#6b7280' }}>Customer: </span><strong>{order.customerName}</strong></div>
              <div><span style={{ color: '#6b7280' }}>Phone: </span>{order.customerPhone}</div>
              {order.customerEmail && <div><span style={{ color: '#6b7280' }}>Email: </span>{order.customerEmail}</div>}
              {order.deliveryAddress && <div><span style={{ color: '#6b7280' }}>Address: </span>{order.deliveryAddress}</div>}
            </div>

            {/* Items table */}
            <table>
              <thead>
                <tr>
                  <th>#</th>
                  <th>Item</th>
                  <th>Qty</th>
                  <th>Unit Price</th>
                  <th>Subtotal</th>
                </tr>
              </thead>
              <tbody>
                {order.items.map((item, i) => (
                  <tr key={i}>
                    <td style={{ color: '#9ca3af', fontSize: '0.8rem' }}>{i + 1}</td>
                    <td>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                        {item.image ? (
                          <img src={`/uploads/${item.image}`} alt="" style={{ width: 36, height: 36, borderRadius: '0.35rem', objectFit: 'cover', flexShrink: 0 }} />
                        ) : (
                          <div style={{ width: 36, height: 36, background: '#f3f4f6', borderRadius: '0.35rem', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#9ca3af', fontSize: '1rem', flexShrink: 0 }}>📦</div>
                        )}
                        <span style={{ fontWeight: 500, fontSize: '0.875rem' }}>{item.name}</span>
                      </div>
                    </td>
                    <td style={{ fontSize: '0.875rem' }}>{item.quantity} <span style={{ color: '#9ca3af', fontSize: '0.75rem' }}>{item.unit}</span></td>
                    <td style={{ fontSize: '0.875rem' }}>{item.price?.toFixed(2)}</td>
                    <td style={{ fontWeight: 700, fontSize: '0.875rem', color: '#2563eb' }}>{item.subtotal?.toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            {/* Totals */}
            <div style={{ padding: '1rem 1.5rem', borderTop: '1px solid #f3f4f6', background: '#fafafa' }}>
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '0.3rem', fontSize: '0.875rem' }}>
                <div style={{ display: 'flex', gap: '2rem' }}>
                  <span style={{ color: '#6b7280' }}>Subtotal</span>
                  <strong style={{ minWidth: 80, textAlign: 'right' }}>{order.subtotal?.toFixed(2)}</strong>
                </div>
                {order.tax > 0 && (
                  <div style={{ display: 'flex', gap: '2rem' }}>
                    <span style={{ color: '#6b7280' }}>Tax</span>
                    <strong style={{ minWidth: 80, textAlign: 'right' }}>{order.tax?.toFixed(2)}</strong>
                  </div>
                )}
                {order.discount > 0 && (
                  <div style={{ display: 'flex', gap: '2rem' }}>
                    <span style={{ color: '#6b7280' }}>Discount</span>
                    <strong style={{ minWidth: 80, textAlign: 'right', color: '#16a34a' }}>-{order.discount?.toFixed(2)}</strong>
                  </div>
                )}
                <div style={{ display: 'flex', gap: '2rem', borderTop: '2px solid #2563eb', paddingTop: '0.5rem', marginTop: '0.25rem' }}>
                  <span style={{ fontWeight: 700, fontSize: '1rem' }}>Total</span>
                  <strong style={{ minWidth: 80, textAlign: 'right', fontSize: '1.2rem', color: '#2563eb' }}>{order.total?.toFixed(2)}</strong>
                </div>
              </div>
            </div>

            {/* Notes */}
            {(order.customerNote || order.ownerNote) && (
              <div style={{ padding: '0.85rem 1.5rem', borderTop: '1px solid #f3f4f6' }}>
                {order.customerNote && (
                  <div style={{ marginBottom: '0.5rem' }}>
                    <span style={{ fontSize: '0.75rem', color: '#6b7280', fontWeight: 600 }}>Your note: </span>
                    <span style={{ fontSize: '0.8rem' }}>{order.customerNote}</span>
                  </div>
                )}
                {order.ownerNote && (
                  <div style={{ padding: '0.6rem 0.85rem', background: '#f0fdf4', borderRadius: '0.4rem', borderLeft: '3px solid #16a34a' }}>
                    <span style={{ fontSize: '0.75rem', color: '#166534', fontWeight: 600 }}>Store note: </span>
                    <span style={{ fontSize: '0.8rem', color: '#166534' }}>{order.ownerNote}</span>
                  </div>
                )}
              </div>
            )}

            <div style={{ padding: '0.75rem 1.5rem', background: '#f8fafc', borderTop: '1px solid #f3f4f6', textAlign: 'center', fontSize: '0.78rem', color: '#9ca3af' }}>
              {ownerSentQuotation ? 'This is your final quotation from the store.' : 'Waiting for store to review and send your quotation.'}
            </div>
          </div>
        </div>

        {/* ── Right: Info + Downloads ── */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>

          {/* Order info */}
          <div className="card">
            <h3 style={{ fontWeight: 700, marginBottom: '1rem', fontSize: '0.95rem' }}>Order Details</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem', fontSize: '0.875rem' }}>
              {[
                ['Order #', order.orderNumber],
                ['Store', order.storeName],
                ['Items', order.items?.length],
                ['Date', new Date(order.createdAt).toLocaleDateString()],
              ].map(([label, value]) => (
                <div key={label} style={{ display: 'flex', justifyContent: 'space-between', paddingBottom: '0.6rem', borderBottom: '1px solid #f3f4f6' }}>
                  <span style={{ color: '#6b7280' }}>{label}</span>
                  <span style={{ fontWeight: 500 }}>{value}</span>
                </div>
              ))}
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span style={{ color: '#6b7280' }}>Status</span>
                <StatusBadge status={order.status} />
              </div>
            </div>
          </div>

          {/* Download quotation — only if owner sent */}
          {ownerSentQuotation && (
            <div className="card">
              <h3 style={{ fontWeight: 700, marginBottom: '0.5rem', fontSize: '0.95rem' }}>📥 Download Quotation</h3>
              <p style={{ fontSize: '0.8rem', color: '#6b7280', marginBottom: '1rem', lineHeight: 1.5 }}>
                Download your final quotation as PDF or Excel.
              </p>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
                <button
                  className="btn btn-primary"
                  style={{ justifyContent: 'center' }}
                  onClick={() => downloadFile(`/customer/orders/${id}/quotation/pdf`, `quotation-${order.orderNumber}.pdf`)}
                >
                  📄 Download PDF
                </button>
                <button
                  className="btn btn-outline"
                  style={{ justifyContent: 'center', color: '#16a34a', borderColor: '#16a34a' }}
                  onClick={() => downloadFile(`/customer/orders/${id}/quotation/excel`, `quotation-${order.orderNumber}.xlsx`)}
                >
                  📊 Download Excel
                </button>
              </div>
            </div>
          )}

          {/* Waiting card — if owner hasn't sent yet */}
          {!ownerSentQuotation && (
            <div className="card" style={{ textAlign: 'center', padding: '1.5rem' }}>
              <div style={{ fontSize: '2.5rem', marginBottom: '0.75rem' }}>⏳</div>
              <h3 style={{ fontWeight: 600, fontSize: '0.95rem', marginBottom: '0.4rem' }}>Awaiting quotation from store</h3>
              <p style={{ fontSize: '0.8rem', color: '#6b7280', lineHeight: 1.5 }}>
                The store owner will review your order, set pricing details, and send you a final quotation shortly.
              </p>
            </div>
          )}

          {/* Invoice download (if available) */}
          {order.invoicePdfPath && (
            <div className="card">
              <h3 style={{ fontWeight: 700, marginBottom: '0.5rem', fontSize: '0.95rem' }}>🧾 Invoice</h3>
              <p style={{ fontSize: '0.8rem', color: '#6b7280', marginBottom: '1rem' }}>
                Final invoice from the store.
              </p>
              <button
                className="btn btn-success"
                style={{ justifyContent: 'center', width: '100%' }}
                onClick={() => downloadFile(`/customer/orders/${id}/quotation/pdf`, `invoice-${order.orderNumber}.pdf`)}
              >
                📄 Download Invoice PDF
              </button>
            </div>
          )}

          {/* Status timeline */}
          <div className="card">
            <h3 style={{ fontWeight: 700, marginBottom: '1rem', fontSize: '0.95rem' }}>Order Progress</h3>
            {[
              { key: 'submitted',  label: 'Order Submitted',       icon: '🛒', always: true },
              { key: 'quoted',     label: 'Quotation Sent',         icon: '📋', done: ownerSentQuotation },
              { key: 'responded',  label: 'Customer Responded',     icon: '✍️', done: order.quotationAccepted || order.editRequested },
              { key: 'confirmed',  label: 'Order Confirmed',        icon: '✅', done: order.status === 'confirmed' || order.status === 'processing' || order.status === 'completed' },
              { key: 'completed',  label: 'Completed',              icon: '🎉', done: order.status === 'completed' },
            ].map((step) => {
              const isDone = step.always || step.done;
              const isCurrent =
                (!ownerSentQuotation && step.key === 'submitted') ||
                (ownerSentQuotation && !order.quotationAccepted && !order.editRequested && step.key === 'quoted') ||
                (order.editRequested && !order.quotationAccepted && step.key === 'responded') ||
                (order.status === 'confirmed' && step.key === 'confirmed') ||
                (order.status === 'completed' && step.key === 'completed');
              return (
                <div key={step.key} style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', padding: '0.45rem 0', opacity: isDone ? 1 : 0.3 }}>
                  <div style={{
                    width: 30, height: 30, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.85rem', flexShrink: 0,
                    background: isCurrent ? '#dbeafe' : isDone ? '#dcfce7' : '#f3f4f6',
                    border: isCurrent ? '2px solid #2563eb' : isDone ? '2px solid #16a34a' : '2px solid #e5e7eb',
                  }}>
                    {step.icon}
                  </div>
                  <span style={{ fontSize: '0.875rem', fontWeight: isCurrent ? 600 : 400, color: isCurrent ? '#1e40af' : '#374151' }}>
                    {step.label}
                  </span>
                  {isCurrent && <span className="badge badge-blue" style={{ fontSize: '0.7rem', marginLeft: 'auto' }}>Now</span>}
                  {isDone && !isCurrent && <span style={{ marginLeft: 'auto', color: '#16a34a', fontSize: '0.8rem' }}>✓</span>}
                </div>
              );
            })}
            {order.status === 'cancelled' && (
              <div style={{ marginTop: '0.5rem', padding: '0.6rem 0.85rem', background: '#fee2e2', borderRadius: '0.4rem', fontSize: '0.8rem', color: '#991b1b' }}>
                ❌ This order was cancelled.
              </div>
            )}
          </div>

        </div>
      </div>
    </Layout>
  );
}
